import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import {
  MeshStandardNodeMaterial,
  tslFn,
  uv,
  vec3,
  mix,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Text content from config or defaults
  const kickerText = config?.textContent?.kicker || 'AS FEATURED IN';
  const brandTexts = config?.textContent?.brands || [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];

  const gridConfig = {
    tileWidth: 1.0,
    tileHeight: 0.62,
    gap: 0.25,
    cols: 3,
    rows: 2,
    totalWidth: 3.5,
    totalHeight: 1.49,
  };

  // Add key light for anisotropic brushed-metal rake effect
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(Math.cos(THREE.MathUtils.degToRad(35)), Math.sin(THREE.MathUtils.degToRad(35)), 1).normalize().multiplyScalar(5);
  group.add(keyLight);

  // Create kicker text
  const kickerMesh = createText({
    text: kickerText,
    fontSize: 9,
    fontWeight: 700,
    fontFamily: 'JetBrains Mono',
    color: 0xe8ecf2,
    opacity: 1.0,
  });
  if (kickerMesh) {
    kickerMesh.position.y = gridConfig.totalHeight / 2 + 0.3;
    group.add(kickerMesh);
  }

  // Create 3x2 grid of machined tiles
  const tiles = [];
  const tileEasing = 'cubic-bezier(0.25, 0.46, 0.45, 0.94)';

  for (let row = 0; row < gridConfig.rows; row++) {
    for (let col = 0; col < gridConfig.cols; col++) {
      const index = row * gridConfig.cols + col;

      // Calculate tile position (centered grid)
      const x =
        col * (gridConfig.tileWidth + gridConfig.gap) -
        gridConfig.totalWidth / 2 +
        gridConfig.tileWidth / 2;
      const y =
        gridConfig.totalHeight / 2 -
        row * (gridConfig.tileHeight + gridConfig.gap) -
        gridConfig.tileHeight / 2;

      const tileGroup = new THREE.Group();
      tileGroup.position.set(x, y, 0);

      // Tile geometry with machined metal material
      const tileMesh = createMachinedTileMesh(
        gridConfig.tileWidth,
        gridConfig.tileHeight
      );
      tileGroup.add(tileMesh);

      // Text overlay for brand mark
      const textMesh = createText({
        text: brandTexts[index],
        fontSize: 13,
        fontWeight: 700,
        fontFamily: 'JetBrains Mono',
        color: 0xe8ecf2,
        opacity: 0.78,
      });
      if (textMesh) {
        textMesh.position.z = 0.01;
        tileGroup.add(textMesh);
        tileGroup.userData.textMesh = textMesh;
      }

      // Hover interaction handlers
      tileGroup.userData.handlers = {
        mouseenter: () => {
          // Text opacity 0.78 -> 1.0
          if (tileGroup.userData.textMesh?.material) {
            gsap.to(tileGroup.userData.textMesh.material, {
              opacity: 1.0,
              duration: 0.16,
            });
          }
          // Tile translateZ 0 -> 0.05
          gsap.to(tileGroup.position, {
            z: 0.05,
            duration: 0.16,
            ease: tileEasing,
          });
        },
        mouseleave: () => {
          // Text opacity 1.0 -> 0.78
          if (tileGroup.userData.textMesh?.material) {
            gsap.to(tileGroup.userData.textMesh.material, {
              opacity: 0.78,
              duration: 0.16,
            });
          }
          // Tile translateZ 0.05 -> 0
          gsap.to(tileGroup.position, {
            z: 0,
            duration: 0.16,
            ease: tileEasing,
          });
        },
      };

      group.add(tileGroup);
      tiles.push(tileGroup);
    }
  }

  // Mount animation: stagger-cards (top row left-to-right, then bottom)
  tiles.forEach((tile, index) => {
    gsap.from(tile, {
      y: tile.position.y + 0.2,
      opacity: 0,
      duration: 0.5,
      delay: index * 0.08,
      ease: tileEasing,
    });
  });

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP animations
    gsap.killTweensOf(tiles);
    tiles.forEach((tile) => {
      if (tile.userData.textMesh?.material) {
        gsap.killTweensOf(tile.userData.textMesh.material);
      }
    });

    // Dispose geometries and materials
    tiles.forEach((tile) => {
      tile.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });
  };

  return group;
}

function createMachinedTileMesh(width, height) {
  const geometry = new THREE.PlaneGeometry(width, height, 8, 8);

  // Create vertical gradient albedo ramp #1a1a22 -> #121218
  const topColor = vec3(26 / 255, 26 / 255, 34 / 255);
  const botColor = vec3(18 / 255, 18 / 255, 24 / 255);
  const colorNode = mix(topColor, botColor, uv().y);

  // Machined-metal PBR: brushed anisotropy, clearcoat, metalness
  const material = new MeshStandardNodeMaterial();
  material.colorNode = colorNode;
  material.roughness = 0.55;
  material.metalness = 0.5;
  material.clearcoat = 0.2;
  material.anisotropy = 0.6;
  material.anisotropyRotation = 0; // x-aligned

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  return mesh;
}
